def add(cid, label, exact, kind, evidence_class, status, provenance,
        population, assumptions, counter, falsifier, dependency, wording,
        related="", outputs=None):
    claims.append(dict(
        id=cid, label=label, exact_claim=exact, kind=kind,
        evidence_class=evidence_class, status=status,
        source_ids=[p.split(" | ")[0] for p in provenance],
        locators=provenance, outputs=outputs or [],
        population_geography_period_comparator_units=population,
        assumptions_and_uncertainty=assumptions,
        counterevidence_alternative_explanation=counter,
        falsification_or_weakening=falsifier,
        dependencies_next_action_owner=dependency,
        permitted_manuscript_wording=wording, related_claims_figures=related,
    ))


