assert 20 <= len(claims) <= 35

sections = [
    ("Literature review", ("LIT",)),
    ("Gap and novelty", ("GAP", "NOV")),
    ("Research questions", ("RQ",)),
    ("Data", ("DAT",)),
    ("Methodological claims", ("MET",)),
    ("Results", ("RES",)),
    ("Interpretation", ("INT",)),
    ("Limitations", ("LIM",)),
]
lines = [
    "# Article claim checker v00",
    "",
    "Status: initial scientific draft, 20 October 2026. Historical published results and new illustrative EUReCA outputs are distinguished claim by claim. This is not article prose. Source IDs resolve through `../02_evidence/source_ledger.md`, `../00_context/conference_evidence.md`, and the exact paths below. No empirical heating-accuracy claim is asserted.",
    "",
]
fields = [
    ("Exact claim", "exact_claim"), ("Kind", "kind"),
    ("Evidence class", "evidence_class"), ("Status", "status"),
    ("Provenance", "locators"),
    ("Population, geography, period, comparator, and units", "population_geography_period_comparator_units"),
    ("Assumptions and uncertainty", "assumptions_and_uncertainty"),
    ("Counterevidence / alternative explanation", "counterevidence_alternative_explanation"),
    ("What would falsify or weaken the claim", "falsification_or_weakening"),
    ("Required next action / dependency / owner", "dependencies_next_action_owner"),
    ("Permitted manuscript wording", "permitted_manuscript_wording"),
    ("Related claims / proposed tables and figures", "related_claims_figures"),
]
for heading, prefixes in sections:
    lines.extend([f"## {heading}", ""])
    for c in claims:
        if c["id"].split("-")[0] not in prefixes:
            continue
        lines.extend([f"### {c['id']} — {c['label']}", ""])
        for label, key in fields:
            value = c[key]
            if isinstance(value, list):
                value = "; ".join(value)
            lines.append(f"- {label}: {value}")
        lines.append("")

md_path = OUT / "article_claims_v00.md"
json_path = OUT / "claim_ledger_v00.json"
snapshot_path = OUT / "claim_evidence_ledger.json"
for p in (md_path, json_path):
    if p.exists():
        raise SystemExit(f"Immutable v00 exists: {p}")
md_path.write_text("\n".join(lines).rstrip() + "\n", encoding="utf-8")
digest = hashlib.sha256(md_path.read_bytes()).hexdigest()
ledger = {
    "schema_version": "1.0", "version": "v00", "draft_filename": md_path.name,
    "draft_sha256": digest, "prior_input_sha256": None,
    "date": "2026-10-20", "claim_count": len(claims), "claims": claims,
}
json_path.write_text(json.dumps(ledger, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
snapshot_path.write_text(json.dumps({
    "version": "v00", "draft_filename": md_path.name, "draft_sha256": digest,
    "claim_ledger_filename": json_path.name,
    "claim_ledger_sha256": hashlib.sha256(json_path.read_bytes()).hexdigest(),
    "claims": {c["id"]: {k: c[k] for k in ("exact_claim", "kind", "evidence_class", "status", "source_ids", "locators", "outputs", "dependencies_next_action_owner", "permitted_manuscript_wording")} for c in claims},
}, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(json.dumps({"draft": str(md_path), "sha256": digest, "claims": len(claims), "ledger": str(json_path), "snapshot": str(snapshot_path)}))
